DAEMON_IP="10.0.2.1"
DAEMON_PORT=50000

ENB1_S1_ADDR="10.0.1.136"
GNB_S1U_ADDR="10.0.1.112"

ENB1_X2_ADDR="10.0.1.121"
GNB_X2_ADDR="10.0.1.2"

MME1_S1_ADDR="10.0.1.131"

SERVER_ADDR="10.0.1.132"
SGW_S1U_ADDR="10.0.1.133"
SGW_S11_ADDR="10.0.1.134"

ENB_X2U_ADDR="10.0.1.135"
PGW_ADDR="4.7.254.207"

PROXY_SERVER_IP="10.0.2.80"
PDN_IP="4.7.254.208"


-----------------------------------------------------------------------------------------------------
-- ENB CONFIGURATION
-----------------------------------------------------------------------------------------------------
exec('set_enb id=1 plmn=250:255 s1='..ENB1_S1_ADDR..' enb_id_macro=0x12346 daemon='..DAEMON_IP..':'..DAEMON_PORT..' x2='..ENB1_X2_ADDR..' x2u='..ENB_X2U_ADDR..' type=simulated x2_peers=none')
exec('enb_param id=1 drb_id_begin=3 endc_capable_qci=9')
exec('set_cell id=1 enb=1 eci=0x1234601 pci=3:2 tac=222 proxy='..DAEMON_IP..':12219 earfcn=2000:20000 mapped_earfcn=4200:22200 tdd_cell=on mandatory_for_activation=off')
exec('enb_endc_param id=1 control_flow_period=3gpp1 use_nr_ran_cont=on')
exec('enb_endc_param id=1 serving_cell_index_range_scg=8:11')

-----------------------------------------------------------------------------------------------------
-- GNB CONFIGURATION
-----------------------------------------------------------------------------------------------------
exec('set_gnb id=2 type=external plmn=250:255 s1u='..GNB_S1U_ADDR..' x2='..GNB_X2_ADDR..':36422 x2_peers=none')
exec('set_cell id=1 gnb=2 nr_arfcn=2232535:2232535 gscn=23006 eci=0x000021f pci=16:2 tac=4 proxy='..PROXY_SERVER_IP..':9999|'..PROXY_SERVER_IP..':8888 nrci=0x01 tdd_cell=on mandatory_for_activation=off')
exec('set_cell id=2 gnb=2 nr_arfcn=2234199:2234199 gscn=23012 eci=0x000021f pci=17:0 tac=4 proxy='..PROXY_SERVER_IP..':9999|'..PROXY_SERVER_IP..':8888 nrci=0x02 tdd_cell=on mandatory_for_activation=off')
exec('set_cell id=3 gnb=2 nr_arfcn=2235863:2235863 gscn=23018 eci=0x000021f pci=17:1 tac=4 proxy='..PROXY_SERVER_IP..':9999|'..PROXY_SERVER_IP..':8888 nrci=0x03 tdd_cell=on mandatory_for_activation=off')
exec('set_cell id=4 gnb=2 nr_arfcn=2237527:2237527 gscn=23022 eci=0x000021f pci=17:2 tac=4 proxy='..PROXY_SERVER_IP..':9999|'..PROXY_SERVER_IP..':8888 nrci=0x04 tdd_cell=on mandatory_for_activation=off')


-----------------------------------------------------------------------------------------------------
-- EPC CONFIGURATION
-----------------------------------------------------------------------------------------------------
exec('mme_pool_area id=1 mmegi=1 plmn=250:255 tac_list=777,111,222,444,333,1')
exec('set_mme id=1 ip='..DAEMON_IP..':'..DAEMON_PORT..' s1='..MME1_S1_ADDR..':36412 supported_rat=lte pool=1:1')
exec('set_sgw id=1 ip='..DAEMON_IP..':'..DAEMON_PORT..' s1u='..SGW_S1U_ADDR..' s11='..SGW_S11_ADDR..':2153 s5u_snd_buff_size=40M s5u_rcv_buff_size=40M s1u_snd_buff_size=40M s1u_rcv_buff_size=40M gtpu_read_packets_threshold=20')
exec('set_pgw id=1 type=simulated ip='..DAEMON_IP..':'..DAEMON_PORT..' addr='..PGW_ADDR..'/16 apn=lteapn1.com.mnc69.mcc450.gprs devtype=tun devname=tunLTEA13 sgi_rcv_buff_size=20M sgi_snd_buff_size=20M s5u_rcv_buff_size=20M s5u_snd_buff_size=20M gtpu_read_packets_threshold=20')

-----------------------------------------------------------------------------------------------------
-- UEC CONFIGURATION
-----------------------------------------------------------------------------------------------------
exec('set_uec id=1 ip='..DAEMON_IP..':'..DAEMON_PORT..' peer='..DAEMON_IP..':2152 gtpu=off retries=unlimited file=AirPhoneConfig.xml proxy_snd_buf_size=209715200 proxy_rcv_buf_size=209715200 proxy_read_packets_threshold=20')

-----------------------------------------------------------------------------------------------------
-- UE CONFIGURATION
-----------------------------------------------------------------------------------------------------
FIRST_UE_NSA_CELL_1 = 11
END_UE_NSA_CELL_1 = 20
FIRST_UE_NSA_CELL_2 = 111
END_UE_NSA_CELL_2 = 120
IMSI_1 = 21645400
IMSI_2 = 21645500
for UEID = FIRST_UE_NSA_CELL_1, END_UE_NSA_CELL_1 do
    exec('set_ue simulated id='..UEID..' uec=1 release=15 idle_edrx_cycle_len=2 ptw=2.56 sec_key=0102030405060708090A0B0C0D0EFF00 eia=null+snow3g+aes eea=null imsi=250:555:'.. IMSI_1 + UEID - 1)
exec('ue_param id='..UEID..' ue_nr_ dual_conn=eutra_nr ue_eutra_nr_')

--    exec('ue_param id='..UEID..' ue_nr_capabilities=23000000008000003040F1380180020000780000000000001BA40000000000015DA8 dual_conn=eutra_nr ue_eutra_nr_capabilities=010C0402E818C3740CE3A206000004103000402004008080100202004008')

	exec('set_bearer id=2 ue='..UEID..' qci=9 pdn=1 ip=4.7.254.'.. UEID + 1 ..' default=on trf_type=internal')
    exec('uec_param id=1 reordering_window_size=1000 reordering_timer=200')
end

for UEID = FIRST_UE_NSA_CELL_2, END_UE_NSA_CELL_2 do
    exec('set_ue simulated id='..UEID..' uec=1 release=15 idle_edrx_cycle_len=2 ptw=2.56 sec_key=0102030405060708090A0B0C0D0EFF00 eia=null+snow3g+aes eea=null imsi=250:555:'.. IMSI_2 + UEID - 1)
--    exec('ue_param id='..UEID..' ue_nr_capabilities=0300000002000800000180008002002000100000018004000000DE00000000000004E8000200000000020023B0 dual_conn=eutra_nr ue_eutra_nr_capabilities=010804028004136200000001008010020200400808010020')
exec('ue_param id='..UEID..' ue_nr_capabilities=23000000008000003040F1380180020000780000000000001BA40000000000015DA8 dual_conn=eutra_nr ue_eutra_nr_capabilities=010C0402E818C3740CE3A206000004103000402004008080100202004008')
      exec('set_bearer id=2 ue='..UEID..' qci=9 pdn=1 ip=4.7.254.'.. UEID + 1 ..' default=on trf_type=internal')
    exec('uec_param id=1 reordering_window_size=1000 reordering_timer=200')
end
 
-----------------------------------------------------------------------------------------------------
-- OTHER CONFIGURATION
-----------------------------------------------------------------------------------------------------
exec('debug_log level=4')
exec('sim_debug_log level=4 mme=1')
exec('sim_debug_log level=4 pgw=1')
exec('sim_debug_log level=4 uec=1')
exec('sim_debug_log level=4 sgw=1')
exec('link_ctrl_param hb_period=5 hb_retries=5')
exec('sim_debug_log enable_events_date=on')
exec('sim_debug_log enable_debug_date=on')
exec('trace enb=1 protocol=x2 on')
exec('trace uec=1 protocol=rrc,nr_rrc on')
